class Solution {
public:
    int maximumSum(std::vector<int>& nums) {
        std::vector<int> best(82, 0);
        int ans = -1;
        for (int x : nums) {
            int temp = x, d_sum = 0;
            while (temp > 0) {
                d_sum += temp % 10;
                temp /= 10;
            }
            if (best[d_sum] > 0) {
                ans = std::max(ans, best[d_sum] + x);
            }
            best[d_sum] = std::max(best[d_sum], x);
        }
        return ans;
    }
};

