var maximumSum = function(nums) {
    const best = new Array(82).fill(0);
    let ans = -1;
    for (const x of nums) {
        let temp = x, dSum = 0;
        while (temp > 0) {
            dSum += temp % 10;
            temp = Math.floor(temp / 10);
        }
        if (best[dSum] > 0) {
            ans = Math.max(ans, best[dSum] + x);
        }
        best[dSum] = Math.max(best[dSum], x);
    }
    return ans;
};
